// ── Lightbox ──────────────────────────────────────────────────────────────────
function LB({ src, onClose }) {
  useEffect(() => {
    const h = e => e.key === "Escape" && onClose();
    window.addEventListener("keydown", h);
    return () => window.removeEventListener("keydown", h);
  }, [onClose]);
  return (
    <div style={{ position:"fixed",inset:0,zIndex:9999,background:"rgba(0,0,0,0.93)",display:"flex",alignItems:"center",justifyContent:"center",cursor:"zoom-out",padding:"32px" }} onClick={onClose}>
      <img src={src} style={{ maxWidth:"96vw",maxHeight:"90vh",objectFit:"contain",borderRadius:"8px" }} onClick={e=>e.stopPropagation()}/>
      <button onClick={onClose} style={{ position:"fixed",top:"16px",right:"20px",background:"rgba(255,255,255,0.12)",border:"none",color:"#fff",borderRadius:"50%",width:"38px",height:"38px",fontSize:"16px",cursor:"pointer",display:"flex",alignItems:"center",justifyContent:"center" }}>✕</button>
    </div>
  );
}

// ── Zoomable image ────────────────────────────────────────────────────────────
function Zoom({ src, alt, radius="12px", shadow=true }) {
  const [open, setOpen] = useState(false);
  return (
    <>
      <img src={src} alt={alt} onClick={()=>setOpen(true)} style={{
        width:"100%", display:"block", borderRadius:radius,
        boxShadow: shadow ? "0 16px 64px rgba(0,0,0,0.6)" : "none",
        cursor:"zoom-in", transition:"transform 0.2s",
      }}
        onMouseEnter={e=>e.currentTarget.style.transform="scale(1.015)"}
        onMouseLeave={e=>e.currentTarget.style.transform="scale(1)"}
      />
      {open && <LB src={src} onClose={()=>setOpen(false)}/>}
    </>
  );
}

// ── Counter ───────────────────────────────────────────────────────────────────
function Count({ to, suffix="" }) {
  const [n, setN] = useState(0);
  const ref = useRef(null);
  const ran = useRef(false);
  useEffect(() => {
    const ob = new IntersectionObserver(([e]) => {
      if (!e.isIntersecting || ran.current) return;
      ran.current = true;
      const t = Date.now();
      const go = () => {
        const p = Math.min((Date.now()-t)/1800, 1);
        setN(Math.floor((1-Math.pow(1-p,3))*to));
        p < 1 && requestAnimationFrame(go);
      };
      requestAnimationFrame(go);
    }, {threshold:0.4});
    if (ref.current) ob.observe(ref.current);
    return () => ob.disconnect();
  }, [to]);
  return <span ref={ref}>{n}{suffix}</span>;
}

